insert into public.daily_question_templates (id, weekday_slot, sequence, question, theme, active, question_en) values
  ('desideri-27', 4, 27, 'Quale esperienza vorresti regalarci per il prossimo compleanno, il tuo o il mio?', 'desideri', true, 'What experience would you love to give us for the next birthday, yours or mine?'),
  ('desideri-28', 4, 28, 'Se potessimo dedicare un anno a un progetto insieme, quale sceglieresti?', 'desideri', true, 'If we could give a whole year to one project together, which would you pick?'),
  ('desideri-29', 4, 29, 'Quale spettacolo della natura vorresti vedere con me almeno una volta?', 'desideri', true, 'Which wonder of nature would you love to see with me at least once?'),
  ('desideri-30', 4, 30, 'C’è un corso, anche strano, a cui ti iscriveresti con me domani?', 'desideri', true, 'Is there a class, even a strange one, you’d sign up for with me tomorrow?'),
  ('desideri-31', 4, 31, 'Quale weekend a tema ti piacerebbe organizzare per noi due?', 'desideri', true, 'What themed weekend would you love to plan for the two of us?'),
  ('desideri-32', 4, 32, 'Se avessimo una barca per una settimana, dove ci porteresti?', 'desideri', true, 'If we had a boat for a week, where would you take us?'),
  ('desideri-33', 4, 33, 'Quale piccolo lusso ti piacerebbe concederci una volta all’anno?', 'desideri', true, 'What little luxury would you love us to treat ourselves to once a year?'),
  ('desideri-34', 4, 34, 'Quale città vorresti vedere con me sotto la neve?', 'desideri', true, 'Which city would you love to see with me under the snow?'),
  ('desideri-35', 4, 35, 'Cosa ti piacerebbe fare con me per la prima volta la prossima estate?', 'desideri', true, 'What would you love to do with me for the first time next summer?'),
  ('desideri-36', 4, 36, 'Quale evento sportivo ti piacerebbe vedere dal vivo con me?', 'desideri', true, 'Which sports event would you love to watch live with me?'),
  ('desideri-37', 4, 37, 'Quale festa di paese o sagra ti piacerebbe vivere insieme?', 'desideri', true, 'Which local festival or food fair would you love to go to together?'),
  ('desideri-38', 4, 38, 'Se potessimo passare una notte in un posto insolito, dove dormiremmo?', 'desideri', true, 'If we could spend one night somewhere unusual, where would we sleep?'),
  ('desideri-39', 4, 39, 'Quale vecchia passione vorresti riprendere, magari con me accanto?', 'desideri', true, 'Which old passion would you love to pick up again, maybe with me beside you?'),
  ('desideri-40', 4, 40, 'Cosa vorresti imparare da me, se te lo insegnassi?', 'desideri', true, 'What would you like to learn from me, if I taught you?'),
  ('desideri-41', 4, 41, 'Quale montagna, lago o bosco vorresti esplorare con me?', 'desideri', true, 'Which mountain, lake or forest would you love to explore with me?'),
  ('desideri-42', 4, 42, 'Quale serata con i nostri amici ti piacerebbe inventare?', 'desideri', true, 'What evening with our friends would you love to dream up?'),
  ('desideri-43', 4, 43, 'Quale mercatino, negozio o quartiere vorresti girare con me senza fretta?', 'desideri', true, 'Which market, shop or neighbourhood would you love to wander with me, no rush?'),
  ('desideri-44', 4, 44, 'Se potessimo dedicare un giorno a una buona causa, insieme, cosa sceglieresti?', 'desideri', true, 'If we could give one day to a good cause together, what would you choose?'),
  ('desideri-45', 4, 45, 'Quale ricetta della tua famiglia vorresti insegnarmi?', 'desideri', true, 'Which recipe from your family would you love to teach me?'),
  ('desideri-46', 4, 46, 'Quale regalo vorresti fare a noi due tra dieci anni?', 'desideri', true, 'What gift would you love to give the two of us ten years from now?'),
  ('desideri-47', 4, 47, 'Quale viaggio vorresti fare con me solo per mangiare?', 'desideri', true, 'Which trip would you love to take with me just for the food?'),
  ('desideri-48', 4, 48, 'Se potessimo cambiare lavoro insieme per un mese, che lavoro proveremmo?', 'desideri', true, 'If we could both switch jobs for a month, which job would we try?'),
  ('desideri-49', 4, 49, 'Quale serata fuori ti piacerebbe vivere vestendoci eleganti?', 'desideri', true, 'What night out would you love for us, all dressed up?'),
  ('desideri-50', 4, 50, 'Quale angolo d’Italia che non conosci ancora vorresti scoprire con me?', 'desideri', true, 'Which corner of Italy you don’t know yet would you love to discover with me?'),
  ('desideri-51', 4, 51, 'Quale alba o tramonto vorresti guardare con me, e da dove?', 'desideri', true, 'Which sunrise or sunset would you love to watch with me, and from where?'),
  ('desideri-52', 4, 52, 'Nella nostra lista di cose da fare prima dei cento anni, cosa metteresti in cima?', 'desideri', true, 'On our list of things to do before we’re a hundred, what would you put at the top?'),
  ('gioco-27', 6, 27, 'Se fossimo due personaggi di un videogioco, quali sarebbero i nostri poteri speciali?', 'gioco', true, 'If we were two video game characters, what would our special powers be?'),
