  ('noi_adesso-42', 1, 42, 'Che colazione ti piacerebbe trovare domani mattina?', 'noi_adesso', true, 'What breakfast would you love to find tomorrow morning?'),
  ('noi_adesso-43', 1, 43, 'Quale impegno della settimana salteresti volentieri, e cosa faresti al suo posto?', 'noi_adesso', true, 'Which commitment this week would you happily skip, and what would you do instead?'),
  ('noi_adesso-44', 1, 44, 'Cosa ti piacerebbe imparare questo mese?', 'noi_adesso', true, 'What would you like to learn this month?'),
  ('noi_adesso-45', 1, 45, 'C’è una persona che ti va di vedere presto, insieme a me?', 'noi_adesso', true, 'Is there someone you’d like to see soon, together with me?'),
