  ('swipe-091', 1, 'Il mare d’inverno o la montagna d’estate?', '["Mare d’inverno","Montagna d’estate"]'::jsonb, 'mare_inverno_montagna_estate', true, 'The sea in winter or the mountains in summer?', '["Sea in winter","Mountains in summer"]'::jsonb),
