insert into public.bond_quest_templates (key, title, category, rarity, xp, mode, active, title_en) values
  ('any-hug-twenty', 'Abbracciatevi per almeno venti secondi: vince chi molla per ultimo.', 'connection', 'common', 25, 'any', true, 'Hug for at least twenty seconds: whoever lets go last wins.'),
  ('any-compliment-swap', 'Fatevi tre complimenti a testa, uno serio, uno buffo e uno inaspettato.', 'connection', 'common', 25, 'any', true, 'Give each other three compliments each: one serious, one silly, one unexpected.'),
  ('any-childhood-song', 'Fatevi ascoltare a vicenda una canzone della vostra infanzia.', 'discover', 'common', 25, 'any', true, 'Play each other a song from your childhood.'),
  ('any-hidden-note', 'Nascondete un piccolo messaggio in un posto dove verrà trovato per caso.', 'surprise', 'common', 25, 'any', true, 'Hide a little message somewhere it will be found by chance.'),
  ('far-same-dinner', 'Cucinate la stessa ricetta nello stesso momento e confrontate il risultato in foto.', 'fun', 'common', 25, 'far', true, 'Cook the same recipe at the same time and compare the results in photos.'),
  ('near-no-plan-hour', 'Uscite per un’ora senza meta: a ogni incrocio decidete a turno.', 'adventure', 'common', 25, 'near', true, 'Go out for an hour with no destination: take turns deciding at every crossing.'),
  ('any-secret-favour', 'Fatevi a vicenda un piccolo favore segreto, senza dirlo, e vedete chi se ne accorge.', 'surprise', 'uncommon', 40, 'any', true, 'Do each other a small secret favour, without saying so, and see who notices.'),
  ('any-top-five-memories', 'Scrivete a testa la vostra top 5 dei momenti insieme, poi confrontatele.', 'memory', 'uncommon', 40, 'any', true, 'Each write your top 5 moments together, then compare them.'),
  ('any-new-word', 'Inventate una parola tutta vostra e usatela almeno tre volte questa settimana.', 'fun', 'uncommon', 40, 'any', true, 'Invent a word all your own and use it at least three times this week.'),
  ('far-postcard', 'Speditevi a vicenda una cartolina vera, anche dalla vostra città.', 'surprise', 'uncommon', 40, 'far', true, 'Send each other a real postcard, even from your own town.'),
  ('near-dance-kitchen', 'Ballate insieme una canzone intera, dove capita, anche in cucina.', 'fun', 'uncommon', 40, 'near', true, 'Dance a whole song together, wherever you are, even in the kitchen.'),
  ('near-tourists-at-home', 'Fate i turisti nella vostra città per un pomeriggio, foto ricordo comprese.', 'adventure', 'uncommon', 40, 'near', true, 'Play tourists in your own city for an afternoon, souvenir photos included.'),
  ('any-future-letter', 'Scrivetevi una lettera da aprire tra un anno e salvatela in un posto sicuro.', 'memory', 'rare', 60, 'any', true, 'Write each other a letter to open in a year and keep it somewhere safe.'),
  ('far-guided-walk', 'Fate una passeggiata in chiamata, raccontandovi a vicenda cosa vedete.', 'connection', 'rare', 60, 'far', true, 'Take a walk together on a call, describing to each other what you see.'),
  ('near-blind-tasting', 'Preparatevi una degustazione alla cieca di tre cose da indovinare.', 'fun', 'rare', 60, 'near', true, 'Set up a blind tasting of three things for each other to guess.'),
  ('any-perfect-day-plan', 'Organizzate a turno metà di una giornata perfetta, senza svelare il programma.', 'adventure', 'epic', 100, 'any', true, 'Each plan half of a perfect day, without revealing the plan.')
